-- Original position content requested by the owner for the four brands.
-- No salary, benefits, hiring quota or employment terms have been invented.
-- Explicitly run against the intended project; reruns preserve existing CMS edits.
BEGIN;
INSERT INTO public.job_postings (tenant_id,slug,title_tr,department,location,employment_type,level,summary_tr,description_tr,requirements_tr,sort_order,active)
SELECT t.id,v.slug,v.title_tr,v.department,v.location,v.employment_type,v.level,v.summary_tr,v.description_tr,v.requirements_tr,v.sort_order,true
FROM (VALUES
('3dyanimda','3d-baski-uretim-teknisyeni','3D Baskı Üretim Teknisyeni','Üretim','','','','Dijital modellerin baskıya hazırlanmasından son kontrole kadar üretimin her adımında rol alın.','<p>Bu rolde katkınız</p><ul><li>Baskı dosyalarını dilimlemek; yönlendirme ve destek stratejisini değerlendirmek.</li><li>Makine hazırlığını, üretim takibini ve temel bakım kayıtlarını yürütmek.</li><li>Üretilen parçaların görsel ve boyutsal kontrolünü yaparak sonuçları belgelemek.</li></ul><p>Çalışma yeri, çalışma modeli ve diğer koşullar görüşme sürecinde birlikte netleştirilir.</p>','<ul><li>FDM veya reçineli baskı süreçlerine ilgi ve uygulama deneyimi.</li><li>Düzenli kayıt tutma, güvenli çalışma ve detaylara dikkat.</li><li>Kullandığınız ekipmanı ve örnek çalışmalarınızı başvuruda paylaşmanız.</li></ul>',0),
('3dyanimda','3d-modelleme-tasarim-uzmani','3D Modelleme ve Tasarım Uzmanı','Tasarım','','','','Bir eskizi, ölçüyü veya fikri üretilebilir bir modele dönüştürmek için tasarım becerinizi kullanın.','<p>Bu rolde katkınız</p><ul><li>Ürün ve prototip ihtiyaçlarını modelleme briefine dönüştürmek.</li><li>CAD veya yüzey modellerini üretim yönteminin gerekliliklerine göre hazırlamak.</li><li>Tasarım revizyonlarını ve model sürümlerini düzenli biçimde takip etmek.</li></ul><p>Çalışma yeri, çalışma modeli ve diğer koşullar görüşme sürecinde birlikte netleştirilir.</p>','<ul><li>En az bir CAD veya 3D modelleme aracında uygulama deneyimi.</li><li>Ölçülendirme, geometrik bütünlük ve üretilebilirlik konularına dikkat.</li><li>Tasarım yaklaşımınızı anlatan bir portföy veya örnek model.</li></ul>',1),
('3dyanimda','proje-musteri-iletisimi','Proje ve Müşteri İletişimi Sorumlusu','Proje koordinasyonu','','','','Farklı ölçeklerdeki projeleri anlayın; ilk talepten üretim planına kadar iletişimi açık ve düzenli tutun.','<p>Bu rolde katkınız</p><ul><li>Gelen taleplerde kullanım amacı, dosya ve teslimat beklentisini toplamak.</li><li>Teknik ekip ile müşteri arasındaki bilgi ve revizyon akışını takip etmek.</li><li>Teklif ve proje kayıtlarını güncel tutmak.</li></ul><p>Çalışma yeri, çalışma modeli ve diğer koşullar görüşme sürecinde birlikte netleştirilir.</p>','<ul><li>Açık yazılı ve sözlü iletişim becerisi.</li><li>Birden çok işi takip edebilme ve ayrıntıları kayıt altına alma alışkanlığı.</li><li>3D üretim süreçlerini öğrenmeye istek.</li></ul>',2),
('3dsanayi','eklemeli-imalat-proje-muhendisi','Eklemeli İmalat Proje Mühendisi','Mühendislik','','','','Endüstriyel bir ihtiyacın teknik kapsamını belirleyin; tasarım ve üretim kararlarını aynı çerçevede buluşturun.','<p>Bu rolde katkınız</p><ul><li>Kullanım koşullarını ve kritik ölçüleri içeren teknik brief hazırlamak.</li><li>Malzeme, geometri ve üretim yöntemi seçeneklerini değerlendirmek.</li><li>Prototip kontrol sonuçlarını izlemek ve revizyonları koordine etmek.</li></ul><p>Çalışma yeri, çalışma modeli ve diğer koşullar görüşme sürecinde birlikte netleştirilir.</p>','<ul><li>Makine, imalat, mekatronik veya ilgili alanda teknik bilgi.</li><li>Teknik resim okuma ve CAD verisiyle çalışma deneyimi.</li><li>Varsayımları, riskleri ve kontrol gerekliliklerini açıkça belgeleme becerisi.</li></ul>',0),
('3dsanayi','olcum-tarama-teknik-uzmani','3D Tarama ve Ölçüm Teknik Uzmanı','Ölçüm ve dijitalleştirme','','','','Fiziksel parçanın yüzeyini ve geometrisini okunabilir, izlenebilir dijital veriye dönüştürün.','<p>Bu rolde katkınız</p><ul><li>Parçaya uygun tarama hazırlığını ve veri toplama sürecini planlamak.</li><li>Nokta bulutu ve mesh verisini temizlemek; eksik alanları değerlendirmek.</li><li>Ölçüm koşullarını ve çıktı dosyalarını proje kayıtlarıyla birlikte teslim etmek.</li></ul><p>Çalışma yeri, çalışma modeli ve diğer koşullar görüşme sürecinde birlikte netleştirilir.</p>','<ul><li>3D tarama veya teknik ölçüm süreçleri hakkında uygulama bilgisi.</li><li>Geometri, ölçek ve koordinat sistemleriyle çalışabilme.</li><li>Veri kalitesini kontrol etme ve sınırlarını doğru raporlama alışkanlığı.</li></ul>',1),
('3dsanayi','uretim-kalite-teknisyeni','Üretim ve Kalite Kontrol Teknisyeni','Üretim ve kalite','','','','Üretim takibi ile parça kontrolünü birlikte yürütün; tekrar edilebilir süreçler kurulmasına katkı sağlayın.','<p>Bu rolde katkınız</p><ul><li>İş emirlerini, makine hazırlığını ve üretim kayıtlarını takip etmek.</li><li>Son işlem ve montaj hazırlıklarını teknik gerekliliklere göre yapmak.</li><li>Uygunsuzlukları belgelemek ve tekrar üretim kararları için veri toplamak.</li></ul><p>Çalışma yeri, çalışma modeli ve diğer koşullar görüşme sürecinde birlikte netleştirilir.</p>','<ul><li>Teknik resim ve temel ölçüm araçlarına aşinalık.</li><li>Atölye düzeni ve iş güvenliği kurallarına özen.</li><li>Problemleri erken fark etme ve ekip içinde net iletişim kurma becerisi.</li></ul>',2),
('maketyanimda','mimari-modelleme-uzmani','Mimari Modelleme Uzmanı','Mimari tasarım','','','','Mimari projelerin mekânsal anlatımını, maket üretimine uygun dijital modellerle güçlendirin.','<p>Bu rolde katkınız</p><ul><li>Plan ve kesit verilerini ölçekli üç boyutlu modele dönüştürmek.</li><li>Üretim, montaj ve taşıma gereksinimlerine göre model bölümlendirmesi yapmak.</li><li>Cephe, peyzaj ve çevre detaylarını proje anlatımına göre geliştirmek.</li></ul><p>Çalışma yeri, çalışma modeli ve diğer koşullar görüşme sürecinde birlikte netleştirilir.</p>','<ul><li>Mimari çizimleri okuma ve 3D modelleme deneyimi.</li><li>Ölçek, oran ve mekânsal kompozisyon konusunda dikkat.</li><li>Mimari veya ürün modelleme çalışmalarını gösteren portföy.</li></ul>',0),
('maketyanimda','maket-uretim-montaj','Maket Üretim ve Montaj Uzmanı','Atölye','','','','Dijital tasarımın fiziksel bir sunum modeline dönüşmesinde el becerinizi ve malzeme bilginizi kullanın.','<p>Bu rolde katkınız</p><ul><li>Üretilen parçaların temizliğini ve montaj hazırlığını yapmak.</li><li>Model, kaide ve çevre elemanlarını belirlenen plana göre birleştirmek.</li><li>Paketleme öncesi bütünlük ve görsel kalite kontrolünü gerçekleştirmek.</li></ul><p>Çalışma yeri, çalışma modeli ve diğer koşullar görüşme sürecinde birlikte netleştirilir.</p>','<ul><li>Maket, model, prototip veya benzer hassas el işlerinde deneyim.</li><li>Malzeme ve el aletlerini güvenli kullanma alışkanlığı.</li><li>Küçük detaylar üzerinde sabırla ve düzenli çalışma becerisi.</li></ul>',1),
('maketyanimda','maket-yuzey-detay','Yüzey ve Detay Uygulama Uzmanı','Görsel uygulama','','','','Renk, doku ve küçük ayrıntılarla mimari modellerin anlatımını tamamlayın.','<p>Bu rolde katkınız</p><ul><li>Parça yüzeylerini boya ve kaplama uygulamalarına hazırlamak.</li><li>Renk ve doku örneklerini proje hedefleriyle karşılaştırmak.</li><li>Peyzaj, çevre ve sunum detaylarının uygulamasına katkı sağlamak.</li></ul><p>Çalışma yeri, çalışma modeli ve diğer koşullar görüşme sürecinde birlikte netleştirilir.</p>','<ul><li>Boya, yüzey bitirme, modelcilik veya ilgili uygulamalarda deneyim.</li><li>Renk uyumu ve ince işçilik konusunda dikkat.</li><li>Örnek çalışmalarınızı veya uygulama fotoğraflarınızı paylaşmanız.</li></ul>',2),
('parcayanimda','tersine-muhendislik-cad','Parça Modelleme ve Tersine Mühendislik Uzmanı','Tasarım ve mühendislik','','','','Mevcut bir parçanın işlevini anlayın; ölçü ve yüzey verisinden düzenlenebilir tasarım geliştirin.','<p>Bu rolde katkınız</p><ul><li>Referans parçaları ve ölçü verilerini inceleyerek modelleme planı hazırlamak.</li><li>CAD modellerini montaj ilişkileri ve kullanım koşullarını dikkate alarak oluşturmak.</li><li>Prototip geri bildirimlerine göre geometri ve bağlantı detaylarını revize etmek.</li></ul><p>Çalışma yeri, çalışma modeli ve diğer koşullar görüşme sürecinde birlikte netleştirilir.</p>','<ul><li>Parametrik CAD modelleme deneyimi.</li><li>Parça ölçümü, tolerans ve montaj ilişkilerine aşinalık.</li><li>Teknik kararları ve modelleme varsayımlarını belgeleme becerisi.</li></ul>',0),
('parcayanimda','parca-uretim-teknisyeni','Parça Üretim Teknisyeni','Üretim','','','','Kullanım amacına uygun parçaların hazırlanması, üretimi ve son kontrolünde sorumluluk alın.','<p>Bu rolde katkınız</p><ul><li>Baskı hazırlığını ve üretim sırasında parça takibini yürütmek.</li><li>Destek temizliği ve son işlemleri parça gereksinimlerine göre yapmak.</li><li>Ölçü, yüzey ve montaj kontrollerini kayıt altına almak.</li></ul><p>Çalışma yeri, çalışma modeli ve diğer koşullar görüşme sürecinde birlikte netleştirilir.</p>','<ul><li>3D baskı veya benzer teknik üretim uygulamalarına aşinalık.</li><li>Temel ölçüm araçlarıyla çalışabilme.</li><li>Parça işlevini anlama, düzenli çalışma ve problem çözme yaklaşımı.</li></ul>',1),
('parcayanimda','teknik-talep-koordinasyonu','Teknik Talep ve Proje Koordinatörü','Proje koordinasyonu','','','','Bir parça talebinin doğru anlaşılmasını sağlayın; fotoğraf, ölçü ve kullanım bilgisini bir araya getirin.','<p>Bu rolde katkınız</p><ul><li>Müşteriden gelen parça taleplerinde eksik teknik bilgileri belirlemek.</li><li>Modelleme, üretim ve kontrol adımları arasındaki iletişimi takip etmek.</li><li>Proje dosyalarını, teklif durumunu ve müşteri geri bildirimlerini düzenlemek.</li></ul><p>Çalışma yeri, çalışma modeli ve diğer koşullar görüşme sürecinde birlikte netleştirilir.</p>','<ul><li>Teknik konulara ilgi ve güçlü iletişim becerisi.</li><li>Dosya, ölçü ve revizyon takibinde dikkat.</li><li>Üretim ekibine açık ve eksiksiz bilgi aktarma alışkanlığı.</li></ul>',2)
) AS v(brand,slug,title_tr,department,location,employment_type,level,summary_tr,description_tr,requirements_tr,sort_order)
JOIN public.tenants t ON t.slug=v.brand
ON CONFLICT (tenant_id,slug) DO NOTHING;
COMMIT;
